CREATE UNIQUE INDEX "payments_debt_pending_idx" ON "payments" USING btree ("debt_id") WHERE "payments"."type" = 'DEBT_COLLECTION' AND "payments"."status" = 'PENDING';--> statement-breakpoint
ALTER TABLE "payments" ADD CONSTRAINT "payments_context_valid" CHECK (("payments"."type" = 'CHARGE' AND "payments"."debt_id" IS NULL AND num_nonnulls("payments"."booking_id", "payments"."reservation_id", "payments"."renewal_id") = 1 AND "payments"."rental_id" IS NULL AND "payments"."source_payment_id" IS NULL AND "payments"."provider" IS NOT NULL AND "payments"."payment_code" IS NOT NULL AND "payments"."provider_payment_id" IS NOT NULL AND "payments"."hold_token_hash" IS NOT NULL) OR ("payments"."type" = 'DEPOSIT_REFUND' AND "payments"."debt_id" IS NULL AND num_nonnulls("payments"."booking_id", "payments"."reservation_id") <= 1 AND "payments"."rental_id" IS NOT NULL AND "payments"."renewal_id" IS NULL AND "payments"."source_payment_id" IS NOT NULL AND "payments"."provider" IS NULL AND "payments"."payment_code" IS NULL AND "payments"."provider_payment_id" IS NULL AND "payments"."hold_token_hash" IS NULL AND "payments"."status" IN ('REFUND_PENDING', 'REFUNDED')) OR ("payments"."type" = 'DEBT_COLLECTION' AND "payments"."debt_id" IS NOT NULL AND "payments"."rental_id" IS NOT NULL AND num_nonnulls("payments"."booking_id", "payments"."reservation_id", "payments"."renewal_id", "payments"."source_payment_id", "payments"."hold_token_hash") = 0 AND "payments"."total_amount" > 0 AND (("payments"."provider" IS NULL AND "payments"."payment_code" IS NULL AND "payments"."provider_payment_id" IS NULL AND "payments"."status" = 'SUCCEEDED' AND "payments"."paid_at" IS NOT NULL AND "payments"."recorded_by" IS NOT NULL AND "payments"."method" IS NOT NULL) OR ("payments"."provider" IS NOT NULL AND "payments"."payment_code" IS NOT NULL AND "payments"."provider_payment_id" IS NOT NULL AND "payments"."expires_at" IS NOT NULL AND "payments"."method" IS NULL AND (("payments"."status" = 'SUCCEEDED' AND "payments"."paid_at" IS NOT NULL) OR ("payments"."status" IN ('PENDING', 'FAILED') AND "payments"."paid_at" IS NULL))))));